"""Class 6 Science Chapter 12 Data Module"""

CHAPTER_META = {'title': 'Beyond Earth', 'class_grade': 'Class 6', 'chapter_num': 12, 'theme': 'Curiosity • NEP 2020 Science', 'short_titles': ['Night Caravans', 'Star Patterns', 'Hunter & Dog', 'North Anchor', 'Dark Sky City', 'Star Finder', 'Solar Heart', 'Rocky Four', 'Gas Giants', 'Dwarf Worlds', 'Twinkle or Steady', 'Moon & Craters', 'Touch the Moon', 'Belt of Rocks', 'Cosmic Ice', 'Milky Way', 'Challenge 1', 'Challenge 2', 'Challenge 3', 'Challenge 4']}

SLIDES = [{'id': 1, 'title': 'Night Caravans', 'subtitle': "Yangdol & Dorjay under Nubra's Crystal Sky & Ancient Celestial Navigation", 'concept_html': "\n            <p>High in the cold mountain desert of Nubra in Ladakh, the air is thin, crisp, and completely free from urban haze. Looking up into the deep night sky, twin siblings Yangdol and Dorjay were mesmerized by thousands of dazzling stars glittering like diamond dust across an ink-black canvas.</p>\n            <p class='mt-2'>Their grandfather shared an enchanting historical truth: centuries ago, intrepid Silk Route traders and desert caravans navigated treacherous mountain passes and boundless sandy deserts at night using these exact same celestial beacons long before the magnetic compass was invented!</p>\n            <div class='mt-3 p-3 rounded-xl bg-slate-950/60 border border-slate-800 text-xs text-indigo-300'>\n                ✨ <strong>Celestial Landmark:</strong> Stars maintain virtually fixed relative geometric configurations over human lifetimes, turning the night sky into humanity's oldest, most reliable celestial clock and compass.\n            </div>\n        ", 'spoken_text': 'Welcome to our cosmic journey beyond Earth. High in the cold mountain desert of Nubra in Ladakh, twin siblings Yangdol and Dorjay gazed upward into the crystal-clear night sky. Far from the smoke and glare of modern cities, thousands of brilliant stars sparkled across the dark heavens. For thousands of years, ancient Silk Route caravans and ocean sailors looked up at these exact same stars to navigate across uncharted continents and stormy seas. Let us explore the wonders of the night sky, our solar neighborhood, and the vast universe beyond.', 'lecture_script': 'Welcome to our cosmic journey beyond Earth. High in the cold mountain desert of Nubra in Ladakh, twin siblings Yangdol and Dorjay gazed upward into the crystal-clear night sky. Far from the smoke and glare of modern cities, thousands of brilliant stars sparkled across the dark heavens. For thousands of years, ancient Silk Route caravans and ocean sailors looked up at these exact same stars to navigate across uncharted continents and stormy seas. Let us explore the wonders of the night sky, our solar neighborhood, and the vast universe beyond.', 'checkpoints': [{'question': 'Why is the Nubra Valley in Ladakh considered an exceptional terrestrial site for astronomical sky observation?', 'options': ['It has dense artificial city neon lights on every hill', 'Its high altitude, low humidity, cloudless weather, and minimal light pollution provide pristine atmospheric clarity', "It is located directly on top of the Moon's surface", 'Stars are physically closer to Ladakh than to any other place on Earth'], 'correct': 1, 'explanation': 'High altitude, dry thin air, low atmospheric turbulence, and absence of urban light pollution make Ladakh an ideal astronomical observing window.', 'study_insight': 'Astronomical observatories are intentionally built in high, dry, isolated mountain zones.'}, {'question': 'How did ancient desert caravans and seafaring sailors reliably determine travel directions before the invention of magnetic compasses?', 'options': ['By following migratory bird calls exclusively during dense blizzards', 'By observing the positions of recognizable star patterns and the stationary Pole Star in the night sky', 'By measuring the temperature of sand with wooden rulers', 'By rolling dice at every crossroads'], 'correct': 1, 'explanation': 'Celestial navigation relied on tracking prominent constellations and the stationary Pole Star to identify cardinal directions at night.', 'study_insight': 'The predictable apparent positions of stars provided reliable direction-finding for ancient explorers.'}]}, {'id': 2, 'title': 'Star Patterns', 'subtitle': 'Self-Luminous Stars, Historic Constellations & The 88 IAU Sky Sectors', 'concept_html': "\n            <p>What is a star? A <strong>star</strong> is a colossal, self-luminous cosmic sphere of incandescent plasma held together by its own gravity, producing tremendous heat and light through thermonuclear fusion.</p>\n            <div class='space-y-2 mt-2 text-slate-300'>\n                <p><strong>Constellations:</strong> Ancient civilizations observed imaginative patterns formed by prominent stars, naming them after mythological heroes, animals, and revered deities.</p>\n                <div class='p-3 rounded-xl bg-slate-900 border border-slate-800 text-xs text-indigo-300'>\n                    🌐 <strong>IAU Scientific Standardization:</strong> In the early 20th century, the <strong>International Astronomical Union (IAU)</strong> standardized the night sky, dividing the entire celestial sphere into <strong>88 officially recognized constellations</strong> with precise boundary lines.\n                </div>\n                <p class='text-xs text-slate-400'>Every star, galaxy, or nebular object visible from Earth resides within one of these 88 distinct celestial territories, much like every town belongs to a specific state or province!</p>\n            </div>\n        ", 'spoken_text': 'A star is a colossal, glowing sphere of hot gas that generates its own light and heat through nuclear reactions deep in its core. For millennia, different human cultures connected bright stars with imaginary lines, creating recognizable pictures called constellations. In the early twentieth century, the International Astronomical Union brought scientific order to the heavens by dividing the entire sky into exactly eighty-eight official constellations. Today, every single star and distant galaxy belongs to one of these eighty-eight mapped cosmic regions.', 'lecture_script': 'A star is a colossal, glowing sphere of hot gas that generates its own light and heat through nuclear reactions deep in its core. For millennia, different human cultures connected bright stars with imaginary lines, creating recognizable pictures called constellations. In the early twentieth century, the International Astronomical Union brought scientific order to the heavens by dividing the entire sky into exactly eighty-eight official constellations. Today, every single star and distant galaxy belongs to one of these eighty-eight mapped cosmic regions.', 'checkpoints': [{'question': 'What is the defining astronomical property that distinguishes a star from a planet or moon?', 'options': ['A star shines with its own internally generated light produced by nuclear fusion', 'A star is always made of solid green granite rock', 'A star only reflects sunlight like a giant mirror', 'A star orbits around human-made satellites'], 'correct': 0, 'explanation': 'Stars are self-luminous thermonuclear reactors generating light and heat, whereas planets and moons merely reflect incident light from stars.', 'study_insight': 'Nuclear fusion in stellar cores converts hydrogen into helium, liberating massive electromagnetic energy.'}, {'question': 'Into how many official constellations did the International Astronomical Union (IAU) systematically divide the celestial sphere?', 'options': ['12 constellations', '88 constellations', '365 constellations', '1,000 constellations'], 'correct': 1, 'explanation': 'The IAU adopted 88 official constellations in 1922, mapping the entire sky into contiguous, non-overlapping geometric sectors.', 'study_insight': 'Constellations serve as standardized coordinates for astronomers cataloging deep-sky objects.'}]}, {'id': 3, 'title': 'Hunter & Dog', 'subtitle': "Orion's Belt, Sirius (The Brightest Star), Taurus & Indian Nakshatra Heritage", 'concept_html': "\n            <p>Among the 88 constellations, several majestic star groupings dominate the winter night sky:</p>\n            <div class='grid grid-cols-1 md:grid-cols-2 gap-3 mt-3'>\n                <div class='p-3 rounded-xl bg-slate-950/70 border border-slate-800'>\n                    <h4 class='text-xs font-bold text-indigo-400 uppercase'>Orion (The Celestial Hunter)</h4>\n                    <p class='text-xs text-slate-300 mt-1'>Features an unmistakable straight line of three brilliant stars forming <strong>Orion's Belt</strong> (Mṛgaśīrṣā in Indian astronomy). Its reddish supergiant shoulder star is <strong>Betelgeuse</strong> (called <em>Ārdrā</em> nakshatra), and its icy blue foot star is <strong>Rigel</strong>.</p>\n                </div>\n                <div class='p-3 rounded-xl bg-slate-950/70 border border-slate-800'>\n                    <h4 class='text-xs font-bold text-sky-400 uppercase'>Canis Major & Sirius (Dog Star)</h4>\n                    <p class='text-xs text-slate-300 mt-1'>Following the line of Orion's belt southeast points directly to <strong>Sirius</strong> (Vyādha), the <strong>brightest star in the entire night sky</strong>, radiating with a piercing blue-white glow roughly 8.6 light-years away!</p>\n                </div>\n            </div>\n            <div class='p-3 rounded-xl bg-amber-950/30 border border-amber-500/20 text-xs text-amber-200 mt-3'>\n                🌟 <strong>Indian Nakshatra Heritage:</strong> Indian traditional astronomy divides the ecliptic path into 27 lunar mansions (Nakshatras), celebrating famous asterisms like <em>Krittikā</em> (the Pleiades star cluster) and fiery red <em>Rohiņi</em> (Aldebaran in Taurus).\n            </div>\n        ", 'spoken_text': "One of the most magnificent sights in the winter sky is the constellation Orion, depicted as a mighty celestial hunter. At its heart lies an unmistakable belt of three bright stars in a straight row. If you trace a line through Orion's belt toward the southeast, it leads your eyes directly to Sirius in the constellation Canis Major. Sirius is the brightest star in the entire night sky, blazing with piercing blue-white light. Indian astronomers deeply studied these stars, incorporating them into our heritage of twenty-seven Nakshatras, including Ārdrā, Krittikā, and red Rohiņi.", 'lecture_script': "One of the most magnificent sights in the winter sky is the constellation Orion, depicted as a mighty celestial hunter. At its heart lies an unmistakable belt of three bright stars in a straight row. If you trace a line through Orion's belt toward the southeast, it leads your eyes directly to Sirius in the constellation Canis Major. Sirius is the brightest star in the entire night sky, blazing with piercing blue-white light. Indian astronomers deeply studied these stars, incorporating them into our heritage of twenty-seven Nakshatras, including Ārdrā, Krittikā, and red Rohiņi.", 'checkpoints': [{'question': 'Which star holds the title of the brightest individual star visible in the night sky from Earth?', 'options': ['The Pole Star (Polaris)', 'Sirius (in Canis Major)', 'Betelgeuse (in Orion)', 'Proxima Centauri'], 'correct': 1, 'explanation': "Sirius (the Dog Star) has an apparent magnitude of -1.46, making it visually brighter than any other star in Earth's night sky.", 'study_insight': 'Apparent brightness depends on both intrinsic stellar luminosity and proximity to Earth.'}, {'question': 'Which prominent visual feature makes the constellation Orion (The Hunter) instantly identifiable in the winter sky?', 'options': ['A perfect circle of twenty green stars', 'A straight belt of three bright, evenly spaced stars', 'A single isolated yellow star with zero neighbors', 'A bright square that rotates every minute'], 'correct': 1, 'explanation': "Orion's Belt is formed by three bright stars (Alnitak, Alnilam, Mintaka) in a distinctive straight alignment.", 'study_insight': "Orion's Belt serves as a prime celestial signpost for locating neighboring stars like Sirius and Aldebaran."}]}, {'id': 4, 'title': 'North Anchor', 'subtitle': 'The Pole Star (Dhruva Tārā), Ursa Major Pointers & Cultural Lore', 'concept_html': "\n            <p>While all stars appear to slowly wheel across the night sky from east to west due to Earth's axial rotation, one unique star remains nearly motionless: the <strong>Pole Star (Polaris / Dhruva Tārā)</strong>.</p>\n            <div class='space-y-2 mt-2 text-slate-300'>\n                <ul class='list-disc pl-5 space-y-1.5'>\n                    <li><strong>Why Is It Stationary?</strong> The Pole Star lies almost directly along the northern extension of Earth's rotational axis. As Earth spins on its axis, Polaris appears fixed directly above the true geographic North Pole!</li>\n                    <li><strong>Locating the Pole Star:</strong> Find the famous <strong>Big Dipper (part of Ursa Major / Saptarishi)</strong>, resembling a giant ladle. The two stars at the outer edge of the cup are called <strong>Pointer Stars</strong>. An imaginary line drawn through them points straight to Dhruva Tārā in Ursa Minor!</li>\n                    <li><strong>Indigenous Folk Stories:</strong> Indian cultural traditions view this constellation with rich imagination: some rural communities saw it as an elderly grandmother's cot (*khatiyā*) with three thieves sneaking away, while coastal sailors saw an anchored fishing boat.</li>\n                </ul>\n            </div>\n        ", 'spoken_text': "As Earth spins on its rotational axis, most stars appear to rise in the east and set in the west. However, one remarkable star appears completely stationary: the Pole Star, revered in Indian heritage as Dhruva Tārā. Because Polaris sits directly above Earth's geographic North Pole, it never changes its position, acting as an unwavering northern beacon for travelers. You can easily find it using the seven stars of the Saptarishi, or Big Dipper. Drawing an imaginary line through the two pointer stars on the dipper's bowl leads straight to the Pole Star.", 'lecture_script': "As Earth spins on its rotational axis, most stars appear to rise in the east and set in the west. However, one remarkable star appears completely stationary: the Pole Star, revered in Indian heritage as Dhruva Tārā. Because Polaris sits directly above Earth's geographic North Pole, it never changes its position, acting as an unwavering northern beacon for travelers. You can easily find it using the seven stars of the Saptarishi, or Big Dipper. Drawing an imaginary line through the two pointer stars on the dipper's bowl leads straight to the Pole Star.", 'checkpoints': [{'question': 'Why does the Pole Star (Dhruva Tārā) appear almost completely stationary in the night sky while other stars appear to move?', 'options': ['Because it is glued to the surface of the Moon', "Because it lies almost directly in line with Earth's northern rotational axis", 'Because it is an artificial satellite launched by ancient astronomers', 'Because it burns out and disappears whenever Earth rotates'], 'correct': 1, 'explanation': "Because Polaris is aligned with Earth's northern axis of rotation, planetary spin does not displace its apparent celestial position.", 'study_insight': "The altitude of the Pole Star above the horizon equals the observer's geographic latitude in the Northern Hemisphere."}, {'question': "Which pair of stars in the Big Dipper (Ursa Major / Saptarishi) is used as 'Pointer Stars' to find the Pole Star?", 'options': ['The two stars forming the handle of the ladle', 'The two stars forming the outer bowl edge opposite the handle', "The central three stars of Orion's belt", 'The two brightest stars inside the constellation Taurus'], 'correct': 1, 'explanation': "The two stars on the outer edge of the Big Dipper's bowl (Merak and Dubhe) point in a straight line directly to Polaris.", 'study_insight': 'Extending the distance between the pointer stars roughly 5 times leads directly to Polaris.'}]}, {'id': 5, 'title': 'Dark Sky City', 'subtitle': 'Light Pollution, Hanle Dark Sky Reserve & Night Vision Preparation', 'concept_html': "\n            <p>Why can we see thousands of sparkling stars in rural villages, but barely a dozen dim dots in bustling cities? The answer is <strong>light pollution</strong>:</p>\n            <div class='grid grid-cols-1 md:grid-cols-2 gap-3 mt-3'>\n                <div class='p-3 rounded-xl bg-slate-950/70 border border-slate-800'>\n                    <h4 class='text-xs font-bold text-rose-400 uppercase'>City Skyglow & Pollution</h4>\n                    <p class='text-xs text-slate-300 mt-1'>Streetlights, illuminated billboards, vehicle headlights, and industrial smog scatter photons into the atmosphere, creating a luminous 'skyglow' that drowns out faint cosmic light from distant stars.</p>\n                </div>\n                <div class='p-3 rounded-xl bg-slate-950/70 border border-slate-800'>\n                    <h4 class='text-xs font-bold text-emerald-400 uppercase'>Dark Sky Sanctuaries (Hanle)</h4>\n                    <p class='text-xs text-slate-300 mt-1'>To safeguard pristine night skies for scientific research, India established the <strong>Hanle Dark Sky Reserve</strong> in eastern Ladakh, enforcing strict dark sky protocols so massive optical telescopes can peer billions of light-years into deep space.</p>\n                </div>\n            </div>\n            <div class='p-3 rounded-xl bg-indigo-950/40 border border-indigo-500/30 text-xs text-indigo-200 mt-3'>\n                👁️ <strong>Dark Adaptation Secret:</strong> When heading out for stargazing, your eyes require roughly <strong>20 to 30 minutes in total darkness</strong> to produce rhodopsin pigment and dilate pupils, unlocking true night vision sensitivity!\n            </div>\n        ", 'spoken_text': 'If you look up from a brightly lit city street at night, you can barely see a handful of dim stars. This is caused by light pollution, where excessive artificial streetlights, neon signs, and vehicular glare bounce off airborne dust, washing out the delicate light of distant stars. To protect the night sky for scientific discovery, India established the Hanle Dark Sky Reserve high in Ladakh, creating a pristine sanctuary for deep-space astronomy. When stargazing, patience is key: waiting twenty to thirty minutes away from bright screens allows your eyes to adapt fully to the dark, revealing thousands of hidden stars.', 'lecture_script': 'If you look up from a brightly lit city street at night, you can barely see a handful of dim stars. This is caused by light pollution, where excessive artificial streetlights, neon signs, and vehicular glare bounce off airborne dust, washing out the delicate light of distant stars. To protect the night sky for scientific discovery, India established the Hanle Dark Sky Reserve high in Ladakh, creating a pristine sanctuary for deep-space astronomy. When stargazing, patience is key: waiting twenty to thirty minutes away from bright screens allows your eyes to adapt fully to the dark, revealing thousands of hidden stars.', 'checkpoints': [{'question': "What is the primary cause of 'light pollution' that obscures the view of stars in modern urban centers?", 'options': ['Stars turning off their light when passing over cities', 'Excessive, unshielded artificial lighting from streetlights, buildings, and billboards scattering into the atmosphere', 'The Moon shining ten times brighter above city centers', 'Clouds made exclusively of reflective silver foil'], 'correct': 1, 'explanation': 'Artificial skyglow scatters upward-directed light off atmospheric molecules and dust particles, overpowering the faint contrast of stars.', 'study_insight': 'Shielding streetlights downward significantly reduces urban skyglow without reducing ground illumination.'}, {'question': "Where is India's premier officially notified Dark Sky Reserve established to preserve pristine darkness for deep-space astronomy?", 'options': ['Connaught Place, New Delhi', 'Hanle, Eastern Ladakh', 'Marine Drive, Mumbai', 'Salt Lake, Kolkata'], 'correct': 1, 'explanation': 'The Hanle Dark Sky Reserve is located in high-altitude Changthang, Ladakh, housing the Indian Astronomical Observatory at 4,500 meters altitude.', 'study_insight': "Hanle's high, cloudless, dry desert plateau provides world-class astronomical seeing conditions."}]}, {'id': 6, 'title': 'Star Finder', 'subtitle': 'Activities 12.2 & 12.3: Hands-On Sky Navigations with Digital Maps & Compass', 'concept_html': "\n            <p>Becoming an amateur astronomer is an exhilarating outdoor activity! Activities 12.2 and 12.3 guide you step-by-step through practical sky navigation:</p>\n            <div class='space-y-2 mt-2 text-slate-300'>\n                <ul class='list-disc pl-5 space-y-1.5'>\n                    <li><strong>Preparation:</strong> Choose a clear, moonless night away from glaring streetlights. Carry a star chart or mobile sky app (like Stellarium or Sky Map) in 'red light mode' to preserve night vision.</li>\n                    <li><strong>Activity 12.2 (Find the Pole Star):</strong> Face north. Locate the seven prominent stars of the Big Dipper ladle. Connect the two outer cup stars (Merak and Dubhe) and extend that line roughly 5 times forward to find steady Polaris.</li>\n                    <li><strong>Activity 12.3 (Locate Orion & Sirius):</strong> Look south in winter. Spot the three close, bright belt stars of Orion. Follow the belt line southeast to lock onto brilliant, sparkling Sirius. Follow the belt northwest to locate orange-red Aldebaran in Taurus!</li>\n                </ul>\n            </div>\n        ", 'spoken_text': "Stargazing is an exciting hands-on adventure that anyone can enjoy. In Activity 12.2, you face northward on a clear night to spot the Big Dipper. Following the two pointer stars on the edge of the dipper's bowl leads directly to the Pole Star, fixing your northern horizon. In Activity 12.3, looking toward the southern winter sky reveals Orion the Hunter. Tracing an imaginary line straight through Orion's three belt stars to the left guides your gaze directly to brilliant Sirius, while extending the line to the right points to the fiery red giant Aldebaran. With a simple compass and red flashlight, the entire night sky unfolds like a cosmic map.", 'lecture_script': "Stargazing is an exciting hands-on adventure that anyone can enjoy. In Activity 12.2, you face northward on a clear night to spot the Big Dipper. Following the two pointer stars on the edge of the dipper's bowl leads directly to the Pole Star, fixing your northern horizon. In Activity 12.3, looking toward the southern winter sky reveals Orion the Hunter. Tracing an imaginary line straight through Orion's three belt stars to the left guides your gaze directly to brilliant Sirius, while extending the line to the right points to the fiery red giant Aldebaran. With a simple compass and red flashlight, the entire night sky unfolds like a cosmic map.", 'checkpoints': [{'question': 'Why do professional and amateur astronomers use a red flashlight rather than bright white light while reading star charts outdoors?', 'options': ['Red light is the only color that can shine through paper', 'Red light does not disrupt dark adaptation of human eye rod cells, preserving night vision', 'Red light creates artificial heat that keeps the astronomer warm', 'White light is illegal during the night hours'], 'correct': 1, 'explanation': 'Human eye rods (sensitive to low light) are insensitive to deep red wavelengths, allowing charts to be read without bleaching rhodopsin or resetting dark adaptation.', 'study_insight': 'Preserving pupil dilation and rhodopsin concentration is essential for spotting faint celestial objects.'}, {'question': "If you follow the line of Orion's three belt stars towards the northwest (opposite from Sirius), which bright orange-red star do you encounter in Taurus?", 'options': ['Aldebaran (Rohiņi)', 'Polaris', 'The Sun', 'Alpha Centauri'], 'correct': 0, 'explanation': "Tracing Orion's belt northwest leads directly to the red giant star Aldebaran (Rohiņi in Indian astronomy), marking the fiery eye of Taurus the Bull.", 'study_insight': "Orion's belt acts as a two-way celestial pointer: southeast to Sirius, northwest to Aldebaran."}]}, {'id': 7, 'title': 'Solar Heart', 'subtitle': 'The Sun at 1 Astronomical Unit (AU), Thermonuclear Fusion & Proxima Centauri', 'concept_html': "\n            <p>Our Solar System is anchored by an extraordinary stellar engine: the <strong>Sun</strong>. The Sun is not a planet; it is an average-sized, yellow dwarf main-sequence <strong>star</strong> situated at the focal center of our planetary neighborhood.</p>\n            <div class='space-y-2 mt-2 text-slate-300'>\n                <ul class='list-disc pl-5 space-y-1.5'>\n                    <li><strong>Proximity & The Astronomical Unit (AU):</strong> The Sun is our closest star, positioned roughly <strong>150 million kilometers (1.5 × 10⁸ km)</strong> away from Earth. This average Earth-Sun distance is scientifically defined as <strong>1 Astronomical Unit (1 AU)</strong>. Sunlight traveling at 300,000 km/s takes approximately <strong>8 minutes and 20 seconds</strong> to reach Earth!</li>\n                    <li><strong>Thermonuclear Powerhouse:</strong> Deep within its core, temperatures reach 15 million degrees Celsius, fusing 600 million tons of hydrogen into helium every second, radiating the heat and light that fuels all terrestrial life.</li>\n                    <li><strong>Our Next Stellar Neighbor:</strong> After the Sun, the nearest known star system to Earth is <strong>Proxima Centauri</strong>, located roughly 4.24 light-years (over 40 trillion kilometers) away!</li>\n                </ul>\n            </div>\n        ", 'spoken_text': "At the very heart of our solar system blazes the Sun. The Sun is our closest star, located approximately one hundred and fifty million kilometers away. In astronomy, this fundamental distance is called one Astronomical Unit. Sunlight travels at three hundred thousand kilometers per second, taking about eight minutes and twenty seconds to reach Earth. Inside the Sun's core, immense pressure and heat fuse hydrogen into helium, generating the light and warmth that sustains all living creatures. After the Sun, the next closest star to Earth is Proxima Centauri, lying over forty trillion kilometers away in deep space.", 'lecture_script': "At the very heart of our solar system blazes the Sun. The Sun is our closest star, located approximately one hundred and fifty million kilometers away. In astronomy, this fundamental distance is called one Astronomical Unit. Sunlight travels at three hundred thousand kilometers per second, taking about eight minutes and twenty seconds to reach Earth. Inside the Sun's core, immense pressure and heat fuse hydrogen into helium, generating the light and warmth that sustains all living creatures. After the Sun, the next closest star to Earth is Proxima Centauri, lying over forty trillion kilometers away in deep space.", 'checkpoints': [{'question': "What is the standard astronomical definition of '1 Astronomical Unit' (1 AU)?", 'options': ['The distance between the North Pole and the South Pole of Earth', 'The average distance from the Earth to the Sun (approx. 150 million kilometers)', 'The distance between Earth and the Moon', 'The length of time it takes Jupiter to complete one orbit'], 'correct': 1, 'explanation': '1 AU is defined as the mean distance between Earth and the Sun, approximately 149.6 million km, used as a yardstick across the Solar System.', 'study_insight': 'Using AU scales down colossal solar system distances into manageable units.'}, {'question': 'Excluding our Sun, which star is closest to planet Earth?', 'options': ['Sirius', 'Betelgeuse', 'Proxima Centauri', 'Polaris'], 'correct': 2, 'explanation': "Proxima Centauri, a red dwarf star in the Alpha Centauri system, is Earth's nearest stellar neighbor at roughly 4.24 light-years distance.", 'study_insight': 'Even traveling at the speed of light, a spacecraft would take over 4 years to reach Proxima Centauri.'}]}, {'id': 8, 'title': 'Rocky Four', 'subtitle': 'The Inner Terrestrial Planets: Mercury, Venus (Runaway Greenhouse), Earth & Mars', 'concept_html': "\n            <p>The four planets closest to the Sun are known as the <strong>Inner Planets (Terrestrial Planets)</strong>. They are characterized by compact sizes, high densities, solid silicate rocky crusts, and metallic iron cores:</p>\n            <div class='grid grid-cols-2 sm:grid-cols-4 gap-2 mt-3 text-center'>\n                <div class='p-2 rounded-xl bg-slate-900 border border-slate-800'>\n                    <div class='text-xs font-bold text-amber-400'>Mercury</div>\n                    <p class='text-[10px] text-slate-400 mt-1'>Closest to Sun; cratered, no atmosphere; extreme 430°C day / -180°C night</p>\n                </div>\n                <div class='p-2 rounded-xl bg-slate-900 border border-slate-800'>\n                    <div class='text-xs font-bold text-yellow-300'>Venus</div>\n                    <p class='text-[10px] text-slate-400 mt-1'>Brightest; 96% CO₂ runaway greenhouse makes it hottest (465°C); Morning Star</p>\n                </div>\n                <div class='p-2 rounded-xl bg-slate-900 border border-slate-800'>\n                    <div class='text-xs font-bold text-sky-400'>Earth</div>\n                    <p class='text-[10px] text-slate-400 mt-1'>Our Blue Planet; liquid water, 21% O₂, protective magnetosphere, flourishing life</p>\n                </div>\n                <div class='p-2 rounded-xl bg-slate-900 border border-slate-800'>\n                    <div class='text-xs font-bold text-rose-400'>Mars</div>\n                    <p class='text-[10px] text-slate-400 mt-1'>Red Planet; iron oxide dust; Olympus Mons volcano, polar ice caps, 2 tiny moons</p>\n                </div>\n            </div>\n            <div class='p-3 rounded-xl bg-amber-950/40 border border-amber-500/30 text-xs text-amber-200 mt-3'>\n                🌡️ <strong>The Venus Paradox:</strong> Although Mercury is closest to the Sun, Venus is significantly hotter! Venus's dense atmosphere of carbon dioxide and sulfuric acid clouds acts as an impenetrable blanket, trapping solar heat in a ferocious runaway greenhouse effect.\n            </div>\n        ", 'spoken_text': 'The four planets closest to the Sun are known as the inner terrestrial planets: Mercury, Venus, Earth, and Mars. Unlike the giant outer worlds, these planets are small, dense, and composed of solid rock and metals. Mercury is a cratered, airless world experiencing dramatic temperature extremes. Next is Venus, often called the Morning or Evening Star. Although Mercury is closer to the Sun, Venus is the hottest planet in the solar system, roasting at over four hundred and sixty degrees Celsius because its thick carbon dioxide atmosphere traps heat in an extreme greenhouse effect. Earth is our living blue haven, while Mars glows rust-red due to iron oxide dust across its barren deserts.', 'lecture_script': 'The four planets closest to the Sun are known as the inner terrestrial planets: Mercury, Venus, Earth, and Mars. Unlike the giant outer worlds, these planets are small, dense, and composed of solid rock and metals. Mercury is a cratered, airless world experiencing dramatic temperature extremes. Next is Venus, often called the Morning or Evening Star. Although Mercury is closer to the Sun, Venus is the hottest planet in the solar system, roasting at over four hundred and sixty degrees Celsius because its thick carbon dioxide atmosphere traps heat in an extreme greenhouse effect. Earth is our living blue haven, while Mars glows rust-red due to iron oxide dust across its barren deserts.', 'checkpoints': [{'question': 'Why is Venus significantly hotter (approx. 465°C) than Mercury, even though Mercury orbits much closer to the Sun?', 'options': ['Venus has thousands of active nuclear power plants', 'Venus has an extremely dense atmosphere of 96% carbon dioxide that traps heat in a runaway greenhouse effect', 'Mercury is made entirely of cold liquid ice', 'Venus has four suns orbiting around it'], 'correct': 1, 'explanation': "Venus's dense CO₂ atmosphere generates an extreme greenhouse effect, trapping solar thermal radiation and raising surface temperatures to 465°C.", 'study_insight': 'Atmospheric composition plays a decisive role in determining planetary surface temperatures.'}, {'question': 'What chemical compound covers the surface of Mars, scattering sunlight to give it its distinctive rust-red appearance?', 'options': ['Liquid nitrogen', 'Iron oxide (rust)', 'Copper sulfate crystals', 'Chlorophyll algae'], 'correct': 1, 'explanation': 'The Martian regolith is rich in iron oxide (Fe₂O₃), commonly known as rust, which oxidizes and creates the characteristic red coloration.', 'study_insight': 'Spectroscopic analysis reveals surface mineralogy across celestial bodies.'}]}, {'id': 9, 'title': 'Gas Giants', 'subtitle': "The Majestic Outer Worlds: Jupiter, Saturn's Rings, Uranus & Neptune", 'concept_html': "\n            <p>Beyond the asteroid belt lie the <strong>Outer Planets (Jovian Planets)</strong>. Far larger and more massive than terrestrial worlds, they lack solid surfaces, consisting primarily of deep hydrogen, helium, methane, and water-ammonia atmospheres:</p>\n            <div class='grid grid-cols-2 sm:grid-cols-4 gap-2 mt-3 text-center'>\n                <div class='p-2 rounded-xl bg-slate-900 border border-slate-800'>\n                    <div class='text-xs font-bold text-amber-400'>Jupiter</div>\n                    <p class='text-[10px] text-slate-400 mt-1'>Largest planet; Great Red Spot storm, over 90 moons (Ganymede, Io, Europa)</p>\n                </div>\n                <div class='p-2 rounded-xl bg-slate-900 border border-slate-800'>\n                    <div class='text-xs font-bold text-yellow-300'>Saturn</div>\n                    <p class='text-[10px] text-slate-400 mt-1'>Spectacular rings of ice and rock; lower density than water; giant moon Titan</p>\n                </div>\n                <div class='p-2 rounded-xl bg-slate-900 border border-slate-800'>\n                    <div class='text-xs font-bold text-teal-300'>Uranus</div>\n                    <p class='text-[10px] text-slate-400 mt-1'>Ice giant; cyan methane color; rotates on its side with a 98° axial tilt!</p>\n                </div>\n                <div class='p-2 rounded-xl bg-slate-900 border border-slate-800'>\n                    <div class='text-xs font-bold text-blue-400'>Neptune</div>\n                    <p class='text-[10px] text-slate-400 mt-1'>Farthest official planet; deep cobalt blue, supersonic winds (>2,000 km/h)</p>\n                </div>\n            </div>\n            <p class='text-xs text-slate-300 mt-3'>All four outer giants possess systems of planetary rings made of orbiting ice, dust, and boulders, with Saturn's rings being the most prominent and luminous.</p>\n        ", 'spoken_text': 'Beyond the asteroid belt lie the four colossal outer planets: Jupiter, Saturn, Uranus, and Neptune. Unlike the rocky inner worlds, these giants are composed primarily of swirling hydrogen, helium, methane, and ice, with no solid surface to walk upon. Jupiter is the undisputed king of planets, so massive that over thirteen hundred Earths could fit inside it, home to the centuries-old Great Red Spot anticyclone. Saturn is famed for its breathtaking, shimmering rings made of billions of icy fragments. Uranus and Neptune are chilly ice giants, with Uranus rotating curiously on its side and Neptune howling with supersonic winds over two thousand kilometers per hour.', 'lecture_script': 'Beyond the asteroid belt lie the four colossal outer planets: Jupiter, Saturn, Uranus, and Neptune. Unlike the rocky inner worlds, these giants are composed primarily of swirling hydrogen, helium, methane, and ice, with no solid surface to walk upon. Jupiter is the undisputed king of planets, so massive that over thirteen hundred Earths could fit inside it, home to the centuries-old Great Red Spot anticyclone. Saturn is famed for its breathtaking, shimmering rings made of billions of icy fragments. Uranus and Neptune are chilly ice giants, with Uranus rotating curiously on its side and Neptune howling with supersonic winds over two thousand kilometers per hour.', 'checkpoints': [{'question': 'What unique physical property sets Saturn apart from all other planets in our solar system regarding its overall density?', 'options': ['Saturn is denser than solid gold', "Saturn's average density is less than liquid water (approx. 0.69 g/cm³), meaning it would theoretically float in a colossal ocean", 'Saturn is made entirely of compressed lead', 'Saturn has zero mass'], 'correct': 1, 'explanation': "Composed mostly of light hydrogen and helium gases, Saturn's mean density is roughly 0.687 g/cm³, which is lower than the density of pure water (1.0 g/cm³).", 'study_insight': 'Low density combined with rapid rotation causes Saturn to be visibly flattened at its poles (oblate spheroid).'}, {'question': 'What unusual rotational characteristic distinguishes the ice giant Uranus from other solar system planets?', 'options': ['It does not rotate at all', 'Its rotational axis is tilted by 98 degrees, so it rolls along its orbital path on its side', 'It changes its rotation direction every single day', 'It rotates faster than the speed of light'], 'correct': 1, 'explanation': 'Uranus has an extreme axial tilt of 97.8°, likely caused by a massive protoplanetary collision during the early formation of the Solar System.', 'study_insight': 'Because Uranus rotates on its side, its poles experience 42 years of continuous sunlight followed by 42 years of darkness.'}]}, {'id': 10, 'title': 'Dwarf Worlds', 'subtitle': 'The 2006 IAU Planetary Definition & The Reclassification of Pluto', 'concept_html': "\n            <p>For over seven decades (1930–2006), textbooks listed Pluto as the ninth planet. In 2006, the <strong>International Astronomical Union (IAU)</strong> established three rigorous criteria to define a true planet:</p>\n            <div class='p-3 rounded-xl bg-slate-900 border border-slate-800 text-xs text-slate-300 space-y-1.5 mt-2'>\n                <p>1. Must orbit directly around the Sun.</p>\n                <p>2. Must possess sufficient mass for its self-gravity to shape it into a nearly spherical hydrostatic equilibrium shape.</p>\n                <p>3. <strong>Must have cleared the neighborhood around its orbit</strong> of other competing debris and planetesimals.</p>\n            </div>\n            <p class='text-xs text-slate-300 mt-3'>Pluto easily meets Criteria 1 and 2, but <strong>fails Criterion 3</strong>: it orbits inside the crowded Kuiper Belt surrounded by thousands of icy trans-Neptunian bodies. Hence, the IAU reclassified Pluto, along with Ceres (in the asteroid belt) and Eris, as <strong>dwarf planets</strong>.</p>\n        ", 'spoken_text': 'For over seventy years, Pluto was celebrated as the ninth planet of our solar system. However, in 2006, the International Astronomical Union established a formal scientific definition of a planet. To be classified as a full planet, an object must orbit the Sun, be pulled into a round spherical shape by its own gravity, and possess enough gravitational muscle to clear its orbital neighborhood of competing debris. While Pluto is spherical and orbits the Sun, it travels through the crowded Kuiper Belt packed with thousands of icy objects. Consequently, the IAU reclassified Pluto, alongside Ceres and Eris, into an exciting new category: dwarf planets.', 'lecture_script': 'For over seventy years, Pluto was celebrated as the ninth planet of our solar system. However, in 2006, the International Astronomical Union established a formal scientific definition of a planet. To be classified as a full planet, an object must orbit the Sun, be pulled into a round spherical shape by its own gravity, and possess enough gravitational muscle to clear its orbital neighborhood of competing debris. While Pluto is spherical and orbits the Sun, it travels through the crowded Kuiper Belt packed with thousands of icy objects. Consequently, the IAU reclassified Pluto, alongside Ceres and Eris, into an exciting new category: dwarf planets.', 'checkpoints': [{'question': 'Which of the three official IAU planetary criteria did Pluto fail to satisfy, leading to its reclassification as a dwarf planet in 2006?', 'options': ['It failed to be spherical in shape', 'It failed to clear the neighborhood around its orbital path', 'It stopped revolving around the Sun', 'It lost all its gravitational pull'], 'correct': 1, 'explanation': "Pluto's mass is only a fraction of the total mass in its orbital zone; it shares its orbit with thousands of Kuiper Belt objects and periodically crosses Neptune's orbit.", 'study_insight': 'Scientific definitions evolve as new observational technologies discover thousands of previously unknown celestial bodies.'}, {'question': 'Which dwarf planet is located closest to Earth, orbiting inside the main Asteroid Belt between Mars and Jupiter?', 'options': ['Pluto', 'Ceres', 'Eris', 'Makemake'], 'correct': 1, 'explanation': 'Ceres is the largest object in the asteroid belt and the only dwarf planet located in the inner Solar System.', 'study_insight': 'Ceres contains roughly one-third of the total mass of the entire asteroid belt.'}]}, {'id': 11, 'title': 'Twinkle or Steady', 'subtitle': 'Atmospheric Scintillation: Why Stars Twinkle While Planets Shine Steadily', 'concept_html': "\n            <p>When you gaze into the night sky, you will notice a fascinating optical distinction: <strong>stars twinkle and shimmer vigorously, whereas bright planets shine with a calm, steady glow</strong>. Why?</p>\n            <div class='grid grid-cols-1 md:grid-cols-2 gap-3 mt-3'>\n                <div class='p-3 rounded-xl bg-slate-950/70 border border-slate-800'>\n                    <h4 class='text-xs font-bold text-amber-400 uppercase'>Why Stars Twinkle</h4>\n                    <p class='text-xs text-slate-300 mt-1'>Stars are trillions of kilometers away, acting as microscopic <strong>point sources of light</strong>. As this narrow beam enters Earth's turbulent atmosphere, fluctuating air temperatures and densities continuously refract the beam in zigzags, causing rapid changes in brightness and position (<strong>scintillation</strong>).</p>\n                </div>\n                <div class='p-3 rounded-xl bg-slate-950/70 border border-slate-800'>\n                    <h4 class='text-xs font-bold text-sky-400 uppercase'>Why Planets Shine Steadily</h4>\n                    <p class='text-xs text-slate-300 mt-1'>Planets are much closer to Earth, appearing through telescopes as <strong>extended optical disks</strong> composed of millions of adjacent light points. The atmospheric flickering of different points averages out, neutralizing scintillation into a solid, unwavering beam!</p>\n                </div>\n            </div>\n        ", 'spoken_text': "Have you ever wondered why stars twinkle like diamonds while planets shine with a calm, steady light? The secret lies in Earth's atmosphere. Because stars are trillions of kilometers away, their light arrives as a microscopic, hair-thin point of light. As this delicate beam passes through fluctuating layers of hot and cold atmospheric winds, it gets continuously bent and refracted, making the star appear to flicker and twinkle. Planets, on the other hand, are much closer to Earth. They appear as larger extended disks of light. The atmospheric fluctuations from different edges cancel each other out, giving planets their calm, steady glow.", 'lecture_script': "Have you ever wondered why stars twinkle like diamonds while planets shine with a calm, steady light? The secret lies in Earth's atmosphere. Because stars are trillions of kilometers away, their light arrives as a microscopic, hair-thin point of light. As this delicate beam passes through fluctuating layers of hot and cold atmospheric winds, it gets continuously bent and refracted, making the star appear to flicker and twinkle. Planets, on the other hand, are much closer to Earth. They appear as larger extended disks of light. The atmospheric fluctuations from different edges cancel each other out, giving planets their calm, steady glow.", 'checkpoints': [{'question': "What causes the apparent visual 'twinkling' of distant stars when viewed from Earth's surface?", 'options': ['Stars turning on and off their nuclear cores every second', 'Atmospheric refraction of narrow point-source starlight passing through turbulent air layers of varying temperatures and densities', 'Swallows flying rapidly in front of the telescope lenses', 'The rotation of the Moon casting fast shadows'], 'correct': 1, 'explanation': 'Atmospheric scintillation occurs because turbulent, moving pockets of air with changing refractive indices constantly deflect narrow starlight beams.', 'study_insight': 'In the vacuum of outer space (e.g., viewed from the Hubble or James Webb telescopes), stars do not twinkle at all.'}, {'question': 'Why do planets like Venus and Jupiter appear as steady, non-twinkling disks of light to the naked eye?', 'options': ['Because planets are infinitely farther away than any star', 'Because their relative proximity makes them extended sources of light where multiple flickering points average out to zero net scintillation', 'Because planets emit laser beams that pierce through all air clouds', 'Because planets are covered with solid glass lenses'], 'correct': 1, 'explanation': 'Planets subtend a measurable angular diameter; light coming from across the disk averages out atmospheric fluctuations, providing a steady image.', 'study_insight': 'A non-twinkling bright point in the dawn or dusk sky is almost always a planet rather than a star.'}]}, {'id': 12, 'title': 'Moon & Craters', 'subtitle': "Earth's Natural Satellite: 27.3-Day Orbit, Impact Craters & Vacuum Environment", 'concept_html': "\n            <p>The <strong>Moon</strong> is Earth's only natural satellite, orbiting at an average distance of roughly 384,400 km. It completes one revolution around Earth in approximately <strong>27.3 days</strong>:</p>\n            <div class='space-y-2 mt-2 text-slate-300'>\n                <ul class='list-disc pl-5 space-y-1.5'>\n                    <li><strong>Synchronous Rotation:</strong> The Moon rotates on its axis in the exact same time it takes to orbit Earth (tidal locking). Consequently, the Moon always presents the <strong>same near side</strong> facing Earth!</li>\n                    <li><strong>Impact Craters:</strong> Looking through binoculars reveals thousands of bowl-shaped craters (like Tycho and Copernicus). Because the Moon has <strong>no atmosphere</strong> to burn incoming meteors and zero wind or water to erode soil, crater scars remain perfectly preserved for billions of years!</li>\n                    <li><strong>Hostile Environment:</strong> With no protective atmospheric blanket, lunar daytime temperatures soar to 120°C in direct sunlight and plunge to -130°C in shadow. There is no liquid water, no air to breathe, and total silence.</li>\n                </ul>\n            </div>\n        ", 'spoken_text': "The Moon is Earth's faithful celestial companion, orbiting our planet at a distance of about three hundred and eighty-four thousand kilometers. It takes roughly twenty-seven days to complete one full revolution. Because its rotation speed matches its orbital speed, the Moon always shows the exact same face toward Earth. When viewed through binoculars, the lunar surface is scarred by thousands of impact craters formed by meteorite collisions. Because the Moon lacks an atmosphere, there is no wind, rain, or flowing water to wash these scars away, preserving craters unchanged for billions of years. With no air and extreme temperature swings, the lunar surface is an eerie, silent world.", 'lecture_script': "The Moon is Earth's faithful celestial companion, orbiting our planet at a distance of about three hundred and eighty-four thousand kilometers. It takes roughly twenty-seven days to complete one full revolution. Because its rotation speed matches its orbital speed, the Moon always shows the exact same face toward Earth. When viewed through binoculars, the lunar surface is scarred by thousands of impact craters formed by meteorite collisions. Because the Moon lacks an atmosphere, there is no wind, rain, or flowing water to wash these scars away, preserving craters unchanged for billions of years. With no air and extreme temperature swings, the lunar surface is an eerie, silent world.", 'checkpoints': [{'question': 'Why do ancient impact craters on the Moon remain sharp and perfectly preserved for billions of years, unlike craters on Earth?', 'options': ['Astronauts regularly repair and polish the craters', 'The Moon has no atmosphere, wind, or liquid water to erode, weather, or erase surface craters', "The Moon's crust is made of indestructible diamond", 'Meteorites on the Moon are made of soft sponge'], 'correct': 1, 'explanation': 'Without an atmosphere, the Moon experiences zero weather, wind erosion, or water runoff, keeping meteorite impact features pristine over geological eons.', 'study_insight': "Earth's active tectonic plate movements, vegetation, and hydrologic erosion continually erase terrestrial impact craters."}, {'question': 'Why does an observer on Earth always see the exact same hemisphere of the Moon facing them?', 'options': ['The Moon does not rotate on its axis at all', "The Moon's rotational period on its axis precisely matches its orbital period around Earth (synchronous tidal locking)", 'The backside of the Moon is invisible black matter', 'The Moon is physically attached to Earth by an iron cable'], 'correct': 1, 'explanation': "Tidal friction over billions of years locked the Moon's rotation period to its orbital period (27.3 days), ensuring the same face always points toward Earth.", 'study_insight': "The 'far side' of the Moon was only photographed when human spacecraft orbited behind it in 1959."}]}, {'id': 13, 'title': 'Touch the Moon', 'subtitle': "India's Lunar Odyssey: Chandrayaan Missions & National Space Day (August 23)", 'concept_html': "\n            <p>India's space agency, <strong>ISRO (Indian Space Research Organisation)</strong>, has scripted golden chapters in lunar exploration:</p>\n            <div class='space-y-2 mt-2 text-slate-300'>\n                <ul class='list-disc pl-5 space-y-1.5'>\n                    <li><strong>Chandrayaan-1 (2008):</strong> Carried the Moon Impact Probe (MIP) and Moon Mineralogy Mapper (M3). India made the historic breakthrough discovery of <strong>water molecules (H₂O and hydroxyl)</strong> trapped in polar lunar regolith!</li>\n                    <li><strong>Chandrayaan-3 (August 23, 2023):</strong> India achieved an unprecedented triumph! The <strong>Vikram lander</strong> executed a flawless soft landing near the uncharted <strong>South Pole of the Moon</strong>, deploying the <strong>Pragyan rover</strong> to conduct on-site soil seismology and elemental composition assays.</li>\n                </ul>\n                <div class='p-3 rounded-xl bg-amber-950/40 border border-amber-500/30 text-xs text-amber-200 mt-2'>\n                    🚀 <strong>National Space Day (August 23rd):</strong> Declared by the Government of India to honor the historic soft-landing of Chandrayaan-3, inspiring generations of Indian students to pursue careers in space science and robotics.\n                </div>\n            </div>\n        ", 'spoken_text': "India's space journey to the Moon has inspired the entire world. In 2008, ISRO's Chandrayaan-1 mission made the groundbreaking discovery of water molecules on the Moon, reshaping lunar science forever. On August twenty-third, 2023, India achieved historic glory when the Chandrayaan-3 mission executed a flawless soft landing near the Moon's uncharted south pole. As the Vikram lander touched down, the Pragyan rover rolled onto the lunar soil, leaving India's national emblem imprinted in the dust. To celebrate this historic scientific achievement, August twenty-third is proudly observed across our country as National Space Day.", 'lecture_script': "India's space journey to the Moon has inspired the entire world. In 2008, ISRO's Chandrayaan-1 mission made the groundbreaking discovery of water molecules on the Moon, reshaping lunar science forever. On August twenty-third, 2023, India achieved historic glory when the Chandrayaan-3 mission executed a flawless soft landing near the Moon's uncharted south pole. As the Vikram lander touched down, the Pragyan rover rolled onto the lunar soil, leaving India's national emblem imprinted in the dust. To celebrate this historic scientific achievement, August twenty-third is proudly observed across our country as National Space Day.", 'checkpoints': [{'question': "What historic scientific discovery was made on the lunar surface by India's Chandrayaan-1 orbiter mission in 2008?", 'options': ['Living alien bacteria in volcanic craters', 'Direct definitive evidence of water molecules (H₂O) trapped in the lunar regolith', 'Extensive underground lakes of liquid petrol', 'Fossilized dinosaur bones'], 'correct': 1, 'explanation': "Chandrayaan-1's Moon Mineralogy Mapper detected unambiguous infrared spectral absorption signatures of water molecules and hydroxyl on the lunar surface.", 'study_insight': "Chandrayaan-1 transformed the scientific consensus from a 'bone-dry Moon' to a hydrated celestial body."}, {'question': 'On which calendar date is National Space Day celebrated annually in India to commemorate the historic soft-landing of Chandrayaan-3 near the lunar South Pole?', 'options': ['January 26th', 'August 23rd', 'October 2nd', 'November 14th'], 'correct': 1, 'explanation': 'August 23rd was declared National Space Day to honor the touchdown of the Vikram lander near the lunar south pole on August 23, 2023.', 'study_insight': 'India became the first nation to soft-land near the rugged lunar south polar region.'}]}, {'id': 14, 'title': 'Belt of Rocks', 'subtitle': 'Asteroids: The Rocky Remnants in Orbit Between Mars and Jupiter', 'concept_html': "\n            <p>Between the orbits of Mars and giant Jupiter lies a vast cosmic demolition zone called the <strong>Asteroid Belt</strong>:</p>\n            <div class='space-y-2 mt-2 text-slate-300'>\n                <p><strong>What Are Asteroids?</strong> Asteroids are small, airless, irregularly shaped rocky and metallic bodies left over from the initial formation of our Solar System 4.6 billion years ago.</p>\n                <div class='grid grid-cols-1 md:grid-cols-2 gap-3 mt-2'>\n                    <div class='p-3 rounded-xl bg-slate-900 border border-slate-800'>\n                        <h4 class='text-xs font-bold text-amber-400 uppercase'>Why Did They Not Form a Planet?</h4>\n                        <p class='text-xs text-slate-300 mt-1'>The colossal gravitational tug of neighboring giant Jupiter continuously stirred and accelerated these rocks, causing violent collisions that shattered them rather than letting them coalesce into a single planet!</p>\n                    </div>\n                    <div class='p-3 rounded-xl bg-slate-900 border border-slate-800'>\n                        <h4 class='text-xs font-bold text-sky-400 uppercase'>Composition & Mining Future</h4>\n                        <p class='text-xs text-slate-300 mt-1'>Asteroids range in size from tiny pebbles to massive bodies like Ceres (nearly 1,000 km across). They are rich in carbon, silicates, and valuable industrial metals like nickel, iron, and platinum.</p>\n                    </div>\n                </div>\n            </div>\n        ", 'spoken_text': "Between the orbits of Mars and Jupiter lies a vast celestial highway packed with rocky rubble known as the Asteroid Belt. Asteroids are rocky, metallic remnants left over from the birth of our solar system four point six billion years ago. Why didn't these millions of rocks gather together to form a planet? Giant Jupiter's enormous gravitational pull constantly stirred the region, causing ancient rocks to smash into each other rather than fusing together. Asteroids range from tiny pebbles to giant boulders hundreds of kilometers wide, holding valuable clues to the origin of our solar neighborhood.", 'lecture_script': "Between the orbits of Mars and Jupiter lies a vast celestial highway packed with rocky rubble known as the Asteroid Belt. Asteroids are rocky, metallic remnants left over from the birth of our solar system four point six billion years ago. Why didn't these millions of rocks gather together to form a planet? Giant Jupiter's enormous gravitational pull constantly stirred the region, causing ancient rocks to smash into each other rather than fusing together. Asteroids range from tiny pebbles to giant boulders hundreds of kilometers wide, holding valuable clues to the origin of our solar neighborhood.", 'checkpoints': [{'question': 'Between which two planetary orbits is the main Asteroid Belt situated in our Solar System?', 'options': ['Between Earth and Venus', 'Between Mars and Jupiter', 'Between Saturn and Uranus', 'Between Mercury and the Sun'], 'correct': 1, 'explanation': 'The main asteroid belt occupies the orbital zone roughly 2.1 to 3.3 AU from the Sun, bounded by Mars on the inside and Jupiter on the outside.', 'study_insight': 'Despite movies showing dense swarms, asteroid belt space is mostly empty, with millions of kilometers between large bodies.'}, {'question': 'What prevented the rocky fragments inside the Asteroid Belt from coalescing into a single large terrestrial planet?', 'options': ['The intense gravitational perturbations and orbital resonances of nearby giant Jupiter', 'Extreme heat from the Sun melted them all into gas', 'Human mining operations destroyed the original planet', "Magnetic repulsion from the Moon's orbit"], 'correct': 0, 'explanation': "Jupiter's immense gravity pumped orbital eccentricities into planetesimals, increasing collision velocities from constructive accretion to destructive fragmentation.", 'study_insight': 'Jupiter acted as a gravitational gatekeeper during planetary disk formation.'}]}, {'id': 15, 'title': 'Cosmic Ice', 'subtitle': "Comets: Dirty Snowballs, Sublimating Coma & Halley's 76-Year Cycle", 'concept_html': "\n            <p>While asteroids are dry rocks, <strong>comets</strong> are icy celestial wanderers often described as 'dirty cosmic snowballs':</p>\n            <div class='space-y-2 mt-2 text-slate-300'>\n                <ul class='list-disc pl-5 space-y-1.5'>\n                    <li><strong>Anatomy of a Comet:</strong> The central solid core (<strong>nucleus</strong>) consists of frozen water ice, carbon dioxide, methane, ammonia, and dark organic dust particles.</li>\n                    <li><strong>How Tails Form:</strong> Deep in outer space, comets are frozen and invisible. As an eccentric orbit brings a comet close to the Sun, solar radiation vaporizes (sublimates) the ices directly into gas, forming a glowing envelope (<strong>coma</strong>) and a spectacular luminous <strong>tail</strong> millions of kilometers long!</li>\n                    <li><strong>Tail Points Away from Sun:</strong> Solar wind and radiation pressure always push the gas and dust particles directly <strong>away from the Sun</strong>, regardless of which direction the comet is traveling!</li>\n                    <li><strong>Halley's Comet:</strong> The most famous periodic comet, returning into Earth's view approximately every <strong>75 to 76 years</strong> (last seen in 1986, next expected in 2061).</li>\n                </ul>\n            </div>\n        ", 'spoken_text': "From the deep, freezing fringes of the solar system come comets, often described as dirty cosmic snowballs. A comet's nucleus is composed of frozen water, methane, and ammonia mixed with dark cosmic dust. Far from the Sun, a comet travels silently in the dark. But as its elongated orbit swoops close to solar heat, the ices instantly vaporize, forming a glowing cloud called a coma and sweeping out a magnificent tail millions of kilometers long. Solar wind always blows this glowing tail directly away from the Sun. The most famous visitor is Halley's Comet, which graces our skies once every seventy-six years, scheduled to return in the year 2061.", 'lecture_script': "From the deep, freezing fringes of the solar system come comets, often described as dirty cosmic snowballs. A comet's nucleus is composed of frozen water, methane, and ammonia mixed with dark cosmic dust. Far from the Sun, a comet travels silently in the dark. But as its elongated orbit swoops close to solar heat, the ices instantly vaporize, forming a glowing cloud called a coma and sweeping out a magnificent tail millions of kilometers long. Solar wind always blows this glowing tail directly away from the Sun. The most famous visitor is Halley's Comet, which graces our skies once every seventy-six years, scheduled to return in the year 2061.", 'checkpoints': [{'question': 'In what direction does the luminous tail of a comet always point as it orbits near the Sun?', 'options': ['Directly toward the center of planet Earth', 'Directly away from the Sun, pushed by solar radiation pressure and solar wind', 'Always trailing straight behind the comet like smoke from a car', 'Directly downward toward the South Pole'], 'correct': 1, 'explanation': 'Photons and charged particles emitted by the Sun (solar wind) exert pressure on sublimated gas ions and dust, pushing the tail directly away from the Sun.', 'study_insight': 'A comet travels tail-first when heading back out toward the outer solar system!'}, {'question': "What is the orbital period of the famous Halley's Comet as it travels from the outer solar system to loop around the Sun?", 'options': ['Every 365 days', 'Approximately every 75 to 76 years', 'Once every 10,000 years', 'Every 5 years'], 'correct': 1, 'explanation': "Halley's Comet has a highly eccentric elliptical orbit with an orbital period of roughly 75 to 76 years, last perihelion in 1986, next in mid-2061.", 'study_insight': "Edmond Halley used Newton's laws of gravitation to successfully predict the comet's 1758 return."}]}, {'id': 16, 'title': 'Milky Way', 'subtitle': 'Ākāśha Gangā Spiral Galaxy, Billions of Stars & The Quest for Exoplanets', 'concept_html': "\n            <p>Step outside on a pitch-black night in a dark sky sanctuary, and you will see a faint, luminous arch of pearly mist spanning the sky: our home galaxy, the <strong>Milky Way (Ākāśha Gangā)</strong>.</p>\n            <div class='space-y-2 mt-2 text-slate-300'>\n                <ul class='list-disc pl-5 space-y-1.5'>\n                    <li><strong>Our Island Universe:</strong> A <strong>galaxy</strong> is a colossal gravitationally bound system containing gas, cosmic dust, and anywhere from millions to hundreds of billions of stars. The Milky Way is a barred spiral galaxy spanning over <strong>100,000 light-years across</strong>, holding over 200 billion stars, including our tiny Solar System!</li>\n                    <li><strong>The Vast Observable Universe:</strong> Our galaxy is just one among an estimated <strong>two trillion galaxies</strong> scattered across the cosmic ocean.</li>\n                    <li><strong>The Search for Life (Exoplanets):</strong> Modern space telescopes (like Kepler and James Webb) have discovered thousands of <strong>exoplanets</strong> (planets orbiting distant stars), searching for atmospheric water and biomarkers in 'habitable goldilocks zones'. While Earth remains the only known haven for life today, the search continues!</li>\n                </ul>\n            </div>\n        ", 'spoken_text': 'On clear, moonless nights far from city lights, a luminous river of milky light stretches across the heavens. This is our home galaxy, the Milky Way, celebrated in Indian lore as the celestial Ākāśha Gangā. A galaxy is a majestic cosmic city of stars, gas, and dust held together by gravity. Our Milky Way is a barred spiral galaxy containing more than two hundred billion stars, with our Sun orbiting along one of its spiral arms. Across the vast observable universe lie trillions of other galaxies. Today, astronomers use space telescopes to discover exoplanets orbiting distant stars, hunting for signs of life beyond Earth.', 'lecture_script': 'On clear, moonless nights far from city lights, a luminous river of milky light stretches across the heavens. This is our home galaxy, the Milky Way, celebrated in Indian lore as the celestial Ākāśha Gangā. A galaxy is a majestic cosmic city of stars, gas, and dust held together by gravity. Our Milky Way is a barred spiral galaxy containing more than two hundred billion stars, with our Sun orbiting along one of its spiral arms. Across the vast observable universe lie trillions of other galaxies. Today, astronomers use space telescopes to discover exoplanets orbiting distant stars, hunting for signs of life beyond Earth.', 'checkpoints': [{'question': 'What is the traditional Indian astronomical name for the glowing celestial band of our Milky Way Galaxy visible in dark night skies?', 'options': ['Ākāśha Gangā', 'Dhruva Tārā', 'Saptarishi', 'Mṛgaśīrṣā'], 'correct': 0, 'explanation': 'The Milky Way is traditionally named Ākāśha Gangā in India, poetically envisioned as a celestial river of heavenly light flowing across the night sky.', 'study_insight': 'The milky glow is the combined light of billions of distant, unresolved stars along the galactic disk.'}, {'question': 'What astronomical term describes a planet that orbits around a star outside our own Solar System?', 'options': ['An asteroid', 'An exoplanet (extrasolar planet)', 'A comet', 'A meteoroid'], 'correct': 1, 'explanation': 'An exoplanet (extrasolar planet) is any planet located beyond our Solar System orbiting another parent star or wandering freely in interstellar space.', 'study_insight': 'Astronomers use transit photometry and radial velocity methods to detect thousands of exoplanets.'}]}]

QUIZ_QUESTIONS = [{'id': 1, 'question': 'What is the fundamental scientific difference between a star and a planet?', 'options': ['A star is always made of green solid ice, while a planet is always made of gold', 'A star generates its own light through thermonuclear fusion in its core, whereas a planet only shines by reflecting starlight', 'A star orbits around planets, while planets stay stationary in space', 'A star only shines during morning hours, while planets only appear at midnight'], 'answer': 1, 'explanation': 'Stars are self-luminous cosmic bodies generating immense electromagnetic radiation via nuclear fusion, while planets are non-luminous bodies reflecting starlight.', 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Energy Generation:</strong> Stars have high core temperatures (>10 million Kelvin) enabling hydrogen fusion into helium, radiating continuous light and heat.</p>\n            <p>2. <strong>Reflected Illumination:</strong> Planets lack the critical mass required to ignite nuclear fusion; their luminosity is purely reflected light from their parent star.</p>\n            <p>3. <strong>Conclusion:</strong> Self-luminosity through fusion defines a star (Option B).</p>\n        "}, {'id': 2, 'question': 'How many officially recognized constellations did the International Astronomical Union (IAU) establish to map the entire sky?', 'options': ['12 constellations', '88 constellations', '365 constellations', '100 constellations'], 'answer': 1, 'explanation': 'In 1922, the IAU standardized 88 official constellations, partitioning the entire celestial sphere into defined, non-overlapping borders.', 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Historical Consolidation:</strong> While various cultures identified hundreds of folk constellations, the IAU officially codified 88 modern constellations.</p>\n            <p>2. <strong>Spatial Coverage:</strong> Together, these 88 constellations tile the 41,253 square degrees of the celestial sphere without gaps.</p>\n            <p>3. <strong>Conclusion:</strong> Exactly 88 constellations (Option B).</p>\n        "}, {'id': 3, 'question': 'Which prominent star in the constellation Canis Major holds the distinction of being the brightest individual star in the night sky?', 'options': ['Betelgeuse', 'Sirius (Vyādha)', 'Polaris', 'Rigel'], 'answer': 1, 'explanation': "Sirius (the Dog Star) has an apparent visual magnitude of -1.46, making it brighter than any other star visible in Earth's night sky.", 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Visual Magnitude:</strong> Lower (and negative) magnitude values denote greater brightness. Sirius at -1.46 outshines Canopus (-0.74) and Alpha Centauri (-0.27).</p>\n            <p>2. <strong>Physical Basis:</strong> Sirius is both intrinsically luminous (25 times more luminous than our Sun) and relatively close to Earth (~8.6 light-years).</p>\n            <p>3. <strong>Conclusion:</strong> Sirius is the brightest night star (Option B).</p>\n        "}, {'id': 4, 'question': 'How can an observer on a clear winter night easily locate the brilliant star Sirius using the constellation Orion?', 'options': ['By drawing a line straight through the three belt stars of Orion and extending it toward the southeast', 'By looking directly beneath the North Pole Star', 'By finding the Moon and looking 180 degrees opposite', 'By tracing the tail of the Big Dipper backwards'], 'answer': 0, 'explanation': "Tracing an imaginary line along the three prominent stars of Orion's Belt towards the southeast points directly to dazzling Sirius in Canis Major.", 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Asterism Signpost:</strong> Orion's Belt (Alnitak, Alnilam, Mintaka) forms a prominent three-star alignment in the winter sky.</p>\n            <p>2. <strong>Pointer Vector:</strong> Extending this belt line downward to the southeast leads directly to brilliant blue-white Sirius.</p>\n            <p>3. <strong>Conclusion:</strong> Trace Orion's belt southeast (Option A).</p>\n        "}, {'id': 5, 'question': "Which red supergiant star marks the prominent shoulder of the celestial hunter in the constellation Orion, known as 'Ārdrā' in Indian astronomy?", 'options': ['Rigel', 'Betelgeuse', 'Aldebaran', 'Polaris'], 'answer': 1, 'explanation': "Betelgeuse (Alpha Orionis) is a colossal red supergiant star marking Orion's right shoulder, celebrated as the nakshatra Ārdrā in Indian traditional astronomy.", 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Stellar Characteristics:</strong> Betelgeuse is an aging red supergiant so vast that if placed at the center of our solar system, its surface would engulf the orbit of Mars!</p>\n            <p>2. <strong>Indian Astronomy:</strong> It is revered as the 6th lunar Nakshatra, named Ārdrā.</p>\n            <p>3. <strong>Conclusion:</strong> Betelgeuse (Option B).</p>\n        "}, {'id': 6, 'question': 'Why does the Pole Star (Dhruva Tārā) appear almost completely stationary throughout the night while all other stars appear to rotate?', 'options': ['Because the Pole Star is frozen inside an iceberg at the North Pole', "Because it lies almost directly in line with Earth's northern axis of rotation", 'Because the Pole Star is a reflection of streetlights in the clouds', 'Because Earth only rotates under the southern stars'], 'answer': 1, 'explanation': 'Earth rotates on an imaginary axis extending through the North and South Poles. The Pole Star sits virtually at the northern celestial pole, so planetary spin does not alter its position.', 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Diurnal Motion:</strong> As Earth rotates from west to east, stars appear to trace concentric circular arcs around the celestial poles.</p>\n            <p>2. <strong>Axial Alignment:</strong> Polaris is located within 0.7 degrees of the true northern rotational axis, meaning its apparent circular orbit is virtually imperceptible to the naked eye.</p>\n            <p>3. <strong>Conclusion:</strong> Aligned with Earth's northern rotational axis (Option B).</p>\n        "}, {'id': 7, 'question': "In Activity 12.2, which two stars in the Big Dipper (Ursa Major / Saptarishi) are designated as 'Pointer Stars' to find the Pole Star?", 'options': ["The two stars at the end of the ladle's handle", "The two stars on the outer edge of the ladle's bowl (Merak and Dubhe)", "The central star inside the ladle's bowl", "The three stars of Orion's Belt"], 'answer': 1, 'explanation': "The two outer stars of the Big Dipper's bowl (Merak and Dubhe) point in a straight line directly towards Polaris at roughly five times their separation distance.", 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Asterism Geometry:</strong> Ursa Major includes the 7-star Big Dipper. Four stars form the bowl, three form the curved handle.</p>\n            <p>2. <strong>Pointer Method:</strong> A straight line extending upward from Merak through Dubhe leads directly to Polaris (the tip of Ursa Minor's tail).</p>\n            <p>3. <strong>Conclusion:</strong> The outer edge stars of the bowl (Option B).</p>\n        "}, {'id': 8, 'question': 'In various Indian rural and tribal folk traditions, how was the distinctive seven-star constellation of the Big Dipper imaginatively perceived?', 'options': ['As an electric train running across a track', "As an elderly grandmother's cot (khatiyā) with three thieves sneaking away, or an anchored fishing boat", 'As a flying aeroplane with passenger windows', 'As a solid concrete skyscraper'], 'answer': 1, 'explanation': "Indian oral folklore often characterized the 4 bowl stars as a grandmother's charpai (cot) and the 3 handle stars as thieves sneaking away, or as a boat navigating heavenly waters.", 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Cultural Ethnoastronomy:</strong> Diverse Indian folklore integrated star patterns into daily life stories: the four bedposts of an elder's cot (*khatiyā*) and three pursuing thieves.</p>\n            <p>2. <strong>Classical Tradition:</strong> In Vedic tradition, the same seven stars represent the revered Seven Sages (Saptarishi).</p>\n            <p>3. <strong>Conclusion:</strong> Option B captures these indigenous folk traditions.</p>\n        "}, {'id': 9, 'question': 'What happens to the apparent altitude (height in degrees above the northern horizon) of the Pole Star as an observer travels from the Equator northward toward the North Pole?', 'options': ['The Pole Star drops below the horizon and disappears completely', "The Pole Star's altitude above the northern horizon increases, exactly matching the observer's geographic latitude", 'The Pole Star turns into the planet Mars', 'The Pole Star spins around the Moon every minute'], 'answer': 1, 'explanation': "By spherical geometry, the angular height of Polaris above the northern horizon precisely equals the observer's geographic northern latitude (0° at Equator, 90° at North Pole).", 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Latitude Metric:</strong> At the Equator (0° N), Polaris sits on the northern horizon (0° altitude). In Delhi (28.6° N), Polaris is ~28.6° high. At the North Pole (90° N), it is at the zenith (90°).</p>\n            <p>2. <strong>Navigational Value:</strong> Ancient navigators measured the Pole Star's altitude using astrolabes or sextants to calculate their exact latitude at sea.</p>\n            <p>3. <strong>Conclusion:</strong> Altitude increases to match geographic latitude (Option B).</p>\n        "}, {'id': 10, 'question': 'Which of the following nakshatras in Indian astronomy corresponds to the fiery red giant star Aldebaran in the constellation Taurus?', 'options': ['Rohiņi', 'Ārdrā', 'Krittikā', 'Ashwini'], 'answer': 0, 'explanation': 'Aldebaran (Alpha Tauri), marking the eye of Taurus, is the prominent red giant star known as the Nakshatra Rohiņi in Indian astronomy.', 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Nakshatra Matching:</strong></p>\n            <p>- <em>Rohiņi</em> = Aldebaran (in Taurus)</p>\n            <p>- <em>Ārdrā</em> = Betelgeuse (in Orion)</p>\n            <p>- <em>Krittikā</em> = Pleiades star cluster</p>\n            <p>2. <strong>Conclusion:</strong> Rohiņi corresponds to Aldebaran (Option A).</p>\n        "}, {'id': 11, 'question': "What is 'light pollution', and why does it severely hinder astronomical stargazing in modern metropolitan cities?", 'options': ['It is sunlight that turns the night into boiling steam', 'Excessive, poorly directed artificial urban lighting scatters across atmospheric air and dust, creating a luminous skyglow that drowns out faint stars', 'Light pollution is when stars shine too brightly and hurt human eyes', 'It is the sound of thunder interfering with telescope radio signals'], 'answer': 1, 'explanation': 'Unshielded urban artificial light reflects and scatters off atmospheric particles, creating artificial skyglow that reduces the contrast between stars and the night sky.', 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Rayleigh & Mie Scattering:</strong> Upward artificial streetlights and neon signs bounce off airborne gas molecules and aerosols, producing an illuminated dome over cities.</p>\n            <p>2. <strong>Contrast Loss:</strong> Faint stars and the Milky Way require high contrast against an ink-black sky. Urban skyglow elevates background brightness, obscuring all but the brightest stars and planets.</p>\n            <p>3. <strong>Conclusion:</strong> Option B describes artificial skyglow and contrast loss.</p>\n        "}, {'id': 12, 'question': "Where is the Indian Astronomical Observatory and India's first designated Dark Sky Reserve located?", 'options': ['Marina Beach, Chennai', 'Hanle, Eastern Ladakh', 'Gateway of India, Mumbai', 'Victoria Memorial, Kolkata'], 'answer': 1, 'explanation': 'The Hanle Dark Sky Reserve is located at Hanle in Eastern Ladakh at an altitude of 4,500 meters, home to the Himalayan Chandra Telescope.', 'solution_html': "<p><strong>Step-by-step Astronomical Verification:</strong></p><p>1. <strong>Location Selection:</strong> Large professional optical and infrared telescopes require high elevation, dry air, cloud-free nights, and dark skies far from city lights.</p><p>2. <strong>Hanle:</strong> Located in Eastern Ladakh at 4,500 m above sea level, Hanle houses the Indian Astronomical Observatory and was officially established as India's first Dark Sky Reserve.</p>"}, {'id': 13, 'question': 'Why must an amateur astronomer wait about 20 to 30 minutes in complete darkness before starting to observe faint stars?', 'options': ['To allow the telescope glass to cool down to sub-zero temperatures', 'To allow human eyes to adapt to darkness by dilating pupils and synthesizing the sensitive vision pigment rhodopsin', 'Because stars only appear 30 minutes after sunset', 'To allow the Moon to hide behind the clouds'], 'answer': 1, 'explanation': 'Dark adaptation requires ~20 to 30 minutes for retinal rod cells to accumulate rhodopsin and for pupils to dilate fully, increasing visual light sensitivity by up to 10,000 times.', 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Photoreceptor Physiology:</strong> Bright light bleaches the rod pigment rhodopsin. In darkness, rhodopsin regenerates gradually.</p>\n            <p>2. <strong>Pupillary Response:</strong> Pupils dilate from ~2 mm in daylight to ~7 mm in darkness, allowing significantly more photons to hit the retina.</p>\n            <p>3. <strong>Conclusion:</strong> Dark adaptation takes 20 to 30 minutes (Option B).</p>\n        "}, {'id': 14, 'question': 'What is the primary scientific reason for using a red flashlight rather than a white flashlight while reading star charts outdoors?', 'options': ['Red light is visible from Mars, alerting other astronomers', 'Red light does not bleach retinal rhodopsin, preserving human night-vision dark adaptation', 'Red light changes the temperature of the paper star chart', 'White light attracts nocturnal bears and wolves'], 'answer': 1, 'explanation': 'Retinal rod cells responsible for night vision are insensitive to longer red wavelengths (>650 nm), allowing charts to be read without resetting dark adaptation.', 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Spectral Sensitivity:</strong> Human rod cells peak in sensitivity near 500 nm (blue-green) and drop to near zero in the deep red spectrum.</p>\n            <p>2. <strong>Night Vision Protection:</strong> Dim red light is detected primarily by cone cells in the fovea, leaving rod cells unbleached so dark vision is maintained.</p>\n            <p>3. <strong>Conclusion:</strong> Red light preserves night vision (Option B).</p>\n        "}, {'id': 15, 'question': 'What is the average distance from the Earth to the Sun, and what standard astronomical unit does it define?', 'options': ['About 384,400 km; defined as 1 Lunar Distance', 'Approximately 150 million kilometers (1.5 × 10⁸ km); defined as 1 Astronomical Unit (1 AU)', 'About 1,000 km; defined as 1 Light-Year', 'About 40 trillion km; defined as 1 Parsec'], 'answer': 1, 'explanation': '1 Astronomical Unit (1 AU) is defined as the mean distance between Earth and the Sun, equal to approximately 149,597,870.7 kilometers (~150 million km).', 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Definition:</strong> 1 AU represents the mean semi-major axis of Earth's orbit around the Sun (~150 million km).</p>\n            <p>2. <strong>Light Travel Time:</strong> Traveling at c = 300,000 km/s: Time = (150,000,000 km) / (300,000 km/s) = 500 seconds = 8 minutes and 20 seconds.</p>\n            <p>3. <strong>Conclusion:</strong> Approx. 150 million km = 1 AU (Option B).</p>\n        "}, {'id': 16, 'question': 'Approximately how long does it take for sunlight traveling across space at 300,000 km/s to reach the surface of Earth?', 'options': ['Instantaneously (0 seconds)', 'About 8 minutes and 20 seconds (approx. 500 seconds)', 'Exactly 24 hours', 'Approximately one full year'], 'answer': 1, 'explanation': 'Sunlight traveling at the speed of light (300,000 km/s) traverses the 150 million kilometer distance to Earth in approximately 500 seconds (8 minutes and 20 seconds).', 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Formula:</strong> Time = Distance / Speed.</p>\n            <p>2. <strong>Calculation:</strong> Time = (1.496 × 10⁸ km) / (3.0 × 10⁵ km/s) = 499 seconds ≈ 8 minutes and 19 to 20 seconds.</p>\n            <p>3. <strong>Conclusion:</strong> ~8 minutes and 20 seconds (Option B).</p>\n        "}, {'id': 17, 'question': 'Which star is our closest stellar neighbor in the universe after the Sun?', 'options': ['Sirius', 'Proxima Centauri', 'Betelgeuse', 'Polaris'], 'answer': 1, 'explanation': 'Proxima Centauri is a red dwarf star in the Alpha Centauri system located approximately 4.24 light-years (roughly 40 trillion km) from Earth.', 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Stellar Proximity:</strong> While the Sun is at 1 AU (0.0000158 light-years), the next closest star is Proxima Centauri at 4.246 light-years.</p>\n            <p>2. <strong>Comparison:</strong> Sirius is at 8.6 light-years, Polaris is at ~430 light-years, and Betelgeuse is at ~640 light-years.</p>\n            <p>3. <strong>Conclusion:</strong> Proxima Centauri (Option B).</p>\n        "}, {'id': 18, 'question': 'Which planet is the hottest in the Solar System, and why does its temperature exceed that of Mercury despite being farther from the Sun?', 'options': ['Mars; because of its active red volcanoes', 'Venus; because its dense atmosphere of 96% carbon dioxide creates a fierce runaway greenhouse effect that traps heat at ~465°C', 'Jupiter; because it generates heat through nuclear fusion', 'Mercury; because it is closest to the Sun'], 'answer': 1, 'explanation': "Venus's dense carbon dioxide atmosphere with sulfuric acid cloud decks produces a runaway greenhouse effect, trapping surface heat at a blistering 465°C, hotter than Mercury's 430°C.", 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Mercury's Thermal Reality:</strong> Mercury is airless; its sunlit face reaches 430°C, while its night side drops to -180°C.</p>\n            <p>2. <strong>Venusian Greenhouse Blanket:</strong> Venus's surface atmospheric pressure is 92 times Earth's, consisting of 96.5% CO₂. This extreme greenhouse blanket traps heat day and night at ~465°C.</p>\n            <p>3. <strong>Conclusion:</strong> Venus is the hottest due to runaway greenhouse trapping (Option B).</p>\n        "}, {'id': 19, 'question': "Which characteristic correctly describes the group of planets known as the 'Inner Planets' (Mercury, Venus, Earth, Mars)?", 'options': ['They are giant balls of liquid hydrogen with no solid rock', 'They are relatively small, dense, and composed predominantly of solid silicate rocks and metallic cores', 'They all have giant icy rings and over fifty moons each', 'They have surfaces made of pure frozen methane'], 'answer': 1, 'explanation': 'Inner terrestrial planets are small, rocky, dense bodies composed of silicate mantles surrounding iron-nickel metallic cores, possessing few or no moons.', 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Compositional Zoning:</strong> In the hot inner protoplanetary disk, only refractory materials with high melting points (silicates, metals) could condense into solid planets.</p>\n            <p>2. <strong>Contrast with Giants:</strong> Volatile gases (hydrogen, helium, ices) were pushed outward past the frost line to form the outer giants.</p>\n            <p>3. <strong>Conclusion:</strong> Dense, rocky silicate worlds (Option B).</p>\n        "}, {'id': 20, 'question': "Why is Mars famously nicknamed the 'Red Planet'?", 'options': ['Because its surface is covered with burning red coal fires', 'Because its surface rocks and regolith are rich in iron oxide (rust), which oxidizes and imparts a distinctive reddish-orange hue', 'Because it reflects the red tail-lights of spacecraft', 'Because it has an atmosphere made of red neon gas'], 'answer': 1, 'explanation': "Mars's crust is rich in iron minerals that have oxidized over geological history into iron(III) oxide (Fe₂O₃, commonly rust), tinting the soil and dust red.", 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Mineral Chemistry:</strong> Basaltic crust rocks on Mars weathered in the presence of ancient atmospheric oxidants, forming ferric oxide minerals (haematite and rust).</p>\n            <p>2. <strong>Global Dust Storms:</strong> Fine ferric oxide particles are lifted by winds into the thin Martian atmosphere, casting a global reddish tint.</p>\n            <p>3. <strong>Conclusion:</strong> Surface iron oxide (rust) (Option B).</p>\n        "}, {'id': 21, 'question': 'Which planet is the largest in our Solar System, featuring the centuries-old cyclonic storm known as the Great Red Spot?', 'options': ['Saturn', 'Jupiter', 'Neptune', 'Earth'], 'answer': 1, 'explanation': "Jupiter is the most massive and voluminous planet in the solar system, with a diameter 11 times Earth's and a giant anticyclonic storm called the Great Red Spot.", 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Massive Scale:</strong> Jupiter contains more mass than all other solar system planets combined (2.5 times total planetary mass).</p>\n            <p>2. <strong>The Great Red Spot:</strong> An immense high-pressure storm in Jupiter's southern hemisphere, wider than the diameter of planet Earth, observed for over 300 years.</p>\n            <p>3. <strong>Conclusion:</strong> Jupiter (Option B).</p>\n        "}, {'id': 22, 'question': 'What unique physical property characterizes the gas giant Saturn regarding its average bulk density?', 'options': ['Saturn is denser than pure solid platinum', 'Saturn has an average density of ~0.69 g/cm³, meaning it is less dense than water and would theoretically float in a colossal bathtub', 'Saturn is made of heavy lead that sinks in liquid mercury', "Saturn's density is infinite because it is a black hole"], 'answer': 1, 'explanation': "Composed overwhelmingly of light hydrogen and helium gases, Saturn's bulk density is roughly 0.687 g/cm³, significantly lower than liquid water's 1.0 g/cm³.", 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Density Calculation:</strong> Density = Mass / Volume. Saturn's mass is ~95 Earth masses, but its enormous volume (~764 Earths) yields a very low mean density of 0.687 g/cm³.</p>\n            <p>2. <strong>Theoretical Gedankenexperiment:</strong> Since water has a density of 1.0 g/cm³, Saturn would float if placed in a hypothetical body of water large enough to hold it.</p>\n            <p>3. <strong>Conclusion:</strong> Less dense than water (Option B).</p>\n        "}, {'id': 23, 'question': 'What are the spectacular rings of Saturn primarily composed of?', 'options': ['Solid iron bars welded together by ancient astronauts', 'Billions of individual chunks of water ice, rocky debris, and dust ranging in size from tiny grains to house-sized boulders', 'Glowing neon gas tubes', 'Pure liquid petroleum'], 'answer': 1, 'explanation': "Saturn's rings are a vast disk of orbiting particles consisting of 99% pure water ice fragments with minor silicate dust, ranging from micrometers to several meters in diameter.", 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Ring Dynamics:</strong> The rings span up to 282,000 km in width but are astonishingly paper-thin, typically only 10 to 30 meters thick!</p>\n            <p>2. <strong>Composition:</strong> Spectroscopy confirms they are composed of clean, highly reflective water ice fragments resulting from shredded icy comets or moons.</p>\n            <p>3. <strong>Conclusion:</strong> Orbiting water ice and rocky fragments (Option B).</p>\n        "}, {'id': 24, 'question': 'Why does the ice giant Uranus appear cyan (blue-green) in telescope imagery, and what is notable about its axis of rotation?', 'options': ['It is covered in green grass; its axis is completely straight at 0 degrees', 'Atmospheric methane gas absorbs red light and reflects blue-green light; its rotational axis is tilted by 98 degrees, so it rolls on its side along its orbit', 'It has blue oceans of fresh drinking water; it does not rotate at all', 'It is painted with synthetic blue enamel'], 'answer': 1, 'explanation': 'Atmospheric methane absorbs red photons, giving Uranus its cyan hue. Its extreme 97.8° axial tilt causes it to orbit the Sun on its side.', 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Color Origin:</strong> Upper atmospheric methane (CH₄) gas selectively absorbs red wavelengths of sunlight while scattering and reflecting blue and green light.</p>\n            <p>2. <strong>Orbital Geometry:</strong> An ancient giant impact knocked Uranus onto its side (97.8° tilt), resulting in extreme 42-year polar seasons.</p>\n            <p>3. <strong>Conclusion:</strong> Methane cyan color and rolls on its side (Option B).</p>\n        "}, {'id': 25, 'question': 'Which of the following is an official criterion established by the IAU in 2006 for a celestial body to be classified as a full planet?', 'options': ['It must have at least ten human space stations on its surface', 'It must orbit the Sun, be pulled into a nearly spherical shape by self-gravity, and have cleared the neighborhood around its orbit', 'It must be made entirely of solid diamond', 'It must possess active green plant life'], 'answer': 1, 'explanation': 'The 2006 IAU definition requires three conditions: (1) Sun orbit, (2) hydrostatic equilibrium (spherical shape), and (3) cleared its orbital neighborhood of debris.', 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>IAU Resolution 5A:</strong> Formalized criteria to distinguish classical planets from dwarf planets and small solar system bodies.</p>\n            <p>2. <strong>The Three Tests:</strong> Orbit the Sun, attain hydrostatic roundness, and gravitationally dominate/clear its orbital zone.</p>\n            <p>3. <strong>Conclusion:</strong> Option B states the complete threefold definition.</p>\n        "}, {'id': 26, 'question': "Why did the International Astronomical Union (IAU) reclassify Pluto from a planet to a 'dwarf planet' in 2006?", 'options': ['Pluto stopped revolving around the Sun', 'Pluto failed to clear the neighborhood around its orbit, sharing its orbital path with thousands of icy Kuiper Belt objects', 'Pluto melted into liquid water and evaporated', "Pluto's color changed from blue to pink"], 'answer': 1, 'explanation': "Pluto's mass is far too small to gravitationally clear its orbital zone; it orbits within the crowded Kuiper Belt and periodically crosses Neptune's orbit.", 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Dynamical Dominance:</strong> A true planet clears its orbital zone by accreting, ejecting, or locking debris into resonance. Earth is 1.7 million times the mass of other debris in its zone.</p>\n            <p>2. <strong>Pluto's Ratio:</strong> Pluto is only 0.07 times the mass of other objects in its zone, sharing its space with thousands of Kuiper Belt bodies.</p>\n            <p>3. <strong>Conclusion:</strong> Failed to clear its neighborhood (Option B).</p>\n        "}, {'id': 27, 'question': "What causes the apparent visual 'twinkling' (scintillation) of distant stars when viewed through Earth's atmosphere?", 'options': ['Stars physically pulsate and explode ten times every second', 'Light from point-source stars passes through turbulent atmospheric layers of varying temperatures and densities, causing continuous refraction and flickering', 'Air molecules inside human eyeballs vibrate when looking at stars', 'The Moon casts high-speed shadows across starlight'], 'answer': 1, 'explanation': 'Atmospheric turbulence creates pockets of air with shifting refractive indices that continuously bend starlight rays, causing rapid shifts in brightness and position.', 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Point-Source Geometry:</strong> Due to extreme distances, starlight arrives as a near-perfect single ray of light.</p>\n            <p>2. <strong>Refractive Fluctuations:</strong> Atmospheric wind currents create thermal gradients, deflecting the ray rapidly in random directions (scintillation).</p>\n            <p>3. <strong>Conclusion:</strong> Atmospheric refraction of point-source light (Option B).</p>\n        "}, {'id': 28, 'question': 'Why do planets like Venus, Mars, and Jupiter appear to shine with a calm, steady light rather than twinkling like stars?', 'options': ['Planets are equipped with giant electric battery lights', 'Planets are much closer to Earth, appearing as extended disks of light where multiple flickering points average out to zero net scintillation', "Planets only shine when Earth's atmosphere is completely frozen", 'Planets emit sound waves that cancel air turbulence'], 'answer': 1, 'explanation': 'Because planets are relatively close, they subtend measurable angular disks. Different points across the disk scintillate out of phase, canceling each other out into a steady glow.', 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Extended Source vs. Point Source:</strong> A planetary disk acts as an array of millions of adjacent light points.</p>\n            <p>2. <strong>Statistical Averaging:</strong> When atmospheric turbulence dims light from one edge of the disk, it brightens light from another edge. The integrated light flux remains constant.</p>\n            <p>3. <strong>Conclusion:</strong> Extended disk averages out scintillation (Option B).</p>\n        "}, {'id': 29, 'question': 'Approximately how many days does it take for the Moon to complete one full revolution around the Earth?', 'options': ['24 hours', 'Approximately 27.3 days', '365.25 days', '100 days'], 'answer': 1, 'explanation': 'The Moon completes one orbital revolution around Earth relative to background stars (sidereal month) in approximately 27.3 days.', 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Sidereal Orbit:</strong> The Moon orbits Earth once every 27.32 days relative to the fixed stars.</p>\n            <p>2. <strong>Synodic Month:</strong> Because Earth also orbits the Sun, completing a full cycle of lunar phases (new moon to new moon) takes 29.53 days.</p>\n            <p>3. <strong>Conclusion:</strong> Approximately 27.3 days (Option B).</p>\n        "}, {'id': 30, 'question': 'Why are impact craters so abundant and sharply preserved on the Moon compared to Earth?', 'options': ['The Moon is made of soft clay that dented easily when young', 'The Moon lacks an atmosphere, liquid water, active plate tectonics, and wind to weather, erode, or bury surface craters', 'Alien spaceships built all the craters as landing docks', 'Earth has never been struck by any meteorites in its history'], 'answer': 1, 'explanation': 'Without an atmosphere to burn incoming space rocks, and without wind, rainfall, or tectonic subduction to erode surface topography, lunar craters remain pristine for billions of years.', 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Absence of Weathering:</strong> Earth possesses an active hydrological cycle, wind erosion, vegetation, and volcanic recycling that constantly erase craters.</p>\n            <p>2. <strong>Lunar Stasis:</strong> The geologically inactive, airless, dry Moon preserves ancient impact craters as a cosmic fossil record of solar system history.</p>\n            <p>3. <strong>Conclusion:</strong> Lack of atmosphere, erosion, and water (Option B).</p>\n        "}, {'id': 31, 'question': "What historic scientific discovery was made on the lunar surface by India's Chandrayaan-1 orbiter mission in 2008?", 'options': ['Discovery of active volcanic magma lakes', 'Definitive detection of water molecules (H₂O) and hydroxyl ions trapped in the polar lunar regolith', 'Discovery of alien radio transmission towers', 'Discovery of diamond glaciers in lunar craters'], 'answer': 1, 'explanation': "Chandrayaan-1's Moon Mineralogy Mapper (M3) detected diagnostic 3.0-micrometer infrared absorption bands proving the widespread presence of water and hydroxyl in lunar soil.", 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Historic Breakthrough:</strong> Prior to Chandrayaan-1, the Moon was widely presumed to be bone-dry. The mission discovered water molecules adsorbed onto lunar mineral grains.</p>\n            <p>2. <strong>Moon Impact Probe (MIP):</strong> On November 14, 2008, the MIP instrument confirmed water vapour in the thin lunar exosphere during descent.</p>\n            <p>3. <strong>Conclusion:</strong> Direct detection of water molecules (Option B).</p>\n        "}, {'id': 32, 'question': 'On August 23, 2023, India achieved a historic first in space exploration with Chandrayaan-3. What was this milestone?', 'options': ['First nation to land human astronauts on Mars', 'First nation to successfully soft-land a robotic spacecraft (Vikram lander & Pragyan rover) near the uncharted South Pole of the Moon', 'First nation to build a hotel on the Moon', 'First nation to capture a piece of the Sun'], 'answer': 1, 'explanation': 'Chandrayaan-3 made India the first nation in history to execute a soft landing in the rugged, shadowed lunar south polar region.', 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>South Polar Triumph:</strong> The lunar south pole is scientifically coveted due to permanently shadowed craters holding water ice reservoirs.</p>\n            <p>2. <strong>National Space Day:</strong> In honor of this milestone, August 23rd was officially declared India's National Space Day.</p>\n            <p>3. <strong>Conclusion:</strong> First soft-landing near lunar south pole (Option B).</p>\n        "}, {'id': 33, 'question': "What were the official names of the lander and rover modules of India's historic Chandrayaan-3 mission?", 'options': ['Vikram (Lander) and Pragyan (Rover)', 'Pushpak (Lander) and Rakesh (Rover)', 'Aryabhata (Lander) and Rohini (Rover)', 'Mangal (Lander) and Aditya (Rover)'], 'answer': 0, 'explanation': 'The Chandrayaan-3 landing module was named Vikram (honoring Dr. Vikram Sarabhai, father of the Indian space program) and the 6-wheeled robotic rover was named Pragyan (meaning wisdom).', 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Vikram Lander:</strong> Contained hazard detection cameras and throttleable thrusters to achieve safe touchdown.</p>\n            <p>2. <strong>Pragyan Rover:</strong> 26 kg solar-powered rover equipped with APXS and LIBS spectrometers to assay lunar elemental soil composition.</p>\n            <p>3. <strong>Conclusion:</strong> Vikram and Pragyan (Option A).</p>\n        "}, {'id': 34, 'question': 'Where is the main Asteroid Belt situated within our Solar System?', 'options': ['Between the orbits of Mars and Jupiter', 'Between Mercury and Venus', 'Beyond the orbit of Pluto', 'Between Earth and the Moon'], 'answer': 0, 'explanation': 'The main asteroid belt forms a circumstellar toroidal ring between the orbits of the inner rocky planet Mars and the outer gas giant Jupiter.', 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Orbital Demarcation:</strong> Located roughly 2.2 to 3.2 AU from the Sun, it marks the boundary between terrestrial rocky planets and Jovian gas giants.</p>\n            <p>2. <strong>Content:</strong> Contains millions of rocky bodies, including dwarf planet Ceres and large asteroids Vesta, Pallas, and Hygiea.</p>\n            <p>3. <strong>Conclusion:</strong> Between Mars and Jupiter (Option A).</p>\n        "}, {'id': 35, 'question': "What is the primary physical composition of a comet's solid core (nucleus)?", 'options': ['Solid molten lava and iron', "Frozen water ice, dry ice (carbon dioxide), methane, ammonia, and embedded dark rocky organic dust ('dirty snowball')", 'Liquid petrol and diesel fuel', 'Pure polished glass'], 'answer': 1, 'explanation': 'A comet nucleus is an icy conglomeration of frozen volatile gases (water, CO, CO₂, CH₄) interspersed with mineral silicates and refractory organic dust.', 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Whipple's Model:</strong> Astronomer Fred Whipple famously termed comet nuclei 'dirty snowballs'.</p>\n            <p>2. <strong>Deep Freeze:</strong> Formed in the frigid outer reaches (Kuiper Belt and Oort Cloud), comets preserve primordial matter from the solar system's birth.</p>\n            <p>3. <strong>Conclusion:</strong> Frozen ices mixed with rocky organic dust (Option B).</p>\n        "}, {'id': 36, 'question': 'Why does the luminous tail of a comet always point directly away from the Sun, even when the comet is moving away from the Sun?', 'options': ['Because solar gravity repels ice crystals', 'Because solar radiation pressure (photons) and the outward stream of charged particles (solar wind) constantly push sublimated gas and dust away from the Sun', 'Because the tail is pulled towards the North Pole Star', 'Because comets have jet engines pointed backwards'], 'answer': 1, 'explanation': 'Solar wind and sunlight photon radiation pressure exert outward repulsive forces on sublimated coma ions and micro-dust, blowing them anti-sunward.', 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Dual Tails:</strong> Comets exhibit an ion (plasma) tail pointed straight away along solar wind magnetic field lines, and a curved dust tail lagging behind along its orbital path.</p>\n            <p>2. <strong>Anti-Sunward Vector:</strong> Both tails point generally away from the Sun regardless of the comet's travel direction.</p>\n            <p>3. <strong>Conclusion:</strong> Pushed by solar wind and radiation pressure (Option B).</p>\n        "}, {'id': 37, 'question': "What is the orbital period of the famous Halley's Comet, and in which year is it next predicted to return to perihelion near Earth?", 'options': ['Every 10 years; next expected in 2030', 'Approximately every 75 to 76 years; next expected to appear in the year 2061', 'Every 365 days; next expected tomorrow', 'Once every 1,000 years; next expected in 3000'], 'answer': 1, 'explanation': "Halley's Comet has an orbital period of roughly 75 to 76 years. It last reached perihelion in early 1986 and will return to perihelion in mid-2061.", 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Orbital Mechanics:</strong> Halley travels out beyond Neptune's orbit (aphelion ~35 AU) before gravity pulls it back toward the Sun (perihelion ~0.59 AU).</p>\n            <p>2. <strong>Timeline:</strong> 1986 + 75.3 years ≈ 2061.</p>\n            <p>3. <strong>Conclusion:</strong> ~75–76 years, returning in 2061 (Option B).</p>\n        "}, {'id': 38, 'question': 'What type of galaxy is our home galaxy, the Milky Way (Ākāśha Gangā), and how many stars does it approximately contain?', 'options': ['A tiny spherical dwarf galaxy containing only three stars', 'A giant barred spiral galaxy spanning over 100,000 light-years across, containing between 100 to 400 billion stars', 'A flat square galaxy containing only our Sun and the Moon', 'A dark cloud of dust containing zero stars'], 'answer': 1, 'explanation': 'The Milky Way is a barred spiral galaxy with a central stellar bar and spiral arms, spanning roughly 100,000 light-years and housing over 200 billion stars.', 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Galactic Architecture:</strong> Our Solar System is situated in the Orion-Cygnus spur of the Sagittarius spiral arm, roughly 26,000 light-years from the galactic supermassive black hole (Sagittarius A*).</p>\n            <p>2. <strong>Stellar Population:</strong> Estimates place the stellar count between 100 and 400 billion stars.</p>\n            <p>3. <strong>Conclusion:</strong> Barred spiral galaxy with hundreds of billions of stars (Option B).</p>\n        "}, {'id': 39, 'question': 'What astronomical term refers to a planet that orbits a distant star located outside our own Solar System?', 'options': ['An asteroid', 'An exoplanet (extrasolar planet)', 'A meteorite', 'A brown dwarf star'], 'answer': 1, 'explanation': 'An exoplanet (extrasolar planet) is any planet that revolves around a star other than our Sun in interstellar space.', 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>Discovery Era:</strong> Since the 1990s, telescopes like Kepler, TESS, and James Webb have confirmed over 5,500 exoplanets across the Milky Way.</p>\n            <p>2. <strong>Habitable Zones:</strong> Astronomers specifically search for rocky exoplanets in 'Goldilocks zones' where liquid surface water could exist.</p>\n            <p>3. <strong>Conclusion:</strong> An exoplanet (Option B).</p>\n        "}, {'id': 40, 'question': 'As modern science gazes across the vast observable universe containing over two trillion galaxies, what profound biological reality remains unique to planet Earth?', 'options': ['Earth is the only planet made of solid granite', 'Earth is currently the ONLY celestial body in the known universe confirmed to harbor and sustain biological life', 'Earth is the largest planet in the entire universe', 'Earth is the only planet that possesses gravity'], 'answer': 1, 'explanation': 'Despite extensive searches across thousands of exoplanets and solar system bodies, Earth remains the sole confirmed haven for biological life in the known cosmos.', 'solution_html': "\n            <h4 class='font-bold text-indigo-300 mb-1'>Detailed Solution:</h4>\n            <p>1. <strong>The Cosmic Oasis:</strong> Earth's liquid water, protective magnetosphere, dynamic plate tectonics, and balanced atmospheric oxygen make it uniquely habitable.</p>\n            <p>2. <strong>Ecological Imperative:</strong> As Carl Sagan emphasized in his 'Pale Blue Dot' reflection, this uniqueness underscores humanity's responsibility to cherish and protect our fragile planetary home.</p>\n            <p>3. <strong>Conclusion:</strong> Earth is the only confirmed haven for life (Option B).</p>\n        "}]
